using Condux.Core.CveScanning;
using Xunit;

namespace Condux.Core.Tests;

/// <summary>
/// The Maven arm of <see cref="VulnerableRanges"/>. The bulk of it is <c>Golden/maven-ranges.tsv</c>:
/// real GitHub Maven advisory ranges, versions on and around each bound with the qualifiers real
/// artifacts carry, and the answer Maven 3.9.16 and 4.0.0-rc-7 both give, regenerated by
/// <c>Golden/maven-ranges.py</c>. The matcher reads only the leading numbers (see
/// <see cref="MavenVersion"/>), so it must never confirm what Maven does not, and confirms a floor of
/// what Maven does. The cases written out below name the rules that fixture holds.
/// </summary>
public class MavenVulnerableRangesTests
{
    [Theory]
    // GHSA-5jpm-x58v-624v, netty: ".Final" is the release itself.
    [InlineData("< 4.1.108.Final", "4.1.107.Final", true)]
    [InlineData("< 4.1.108.Final", "4.1.108", false)]
    [InlineData(">= 4.1.108, < 4.2", "4.1.108.Final", true)]
    [InlineData("< 4.1.108.Final", "4.1.108.Final", false)]
    // GHSA-5mg8-w23w-74h3, guava: the numbers decide, whatever the qualifier.
    [InlineData("< 32.0.0-android", "31.1-jre", true)]
    // GHSA-5h9j-q6j2-253f, jetty: identical texts are equal, whatever their qualifiers.
    [InlineData("= 9.4.21.v20190926", "9.4.21.v20190926", true)]
    // GHSA-26vr-8j45-3r4w, jetty: a build of the release sorts above the release.
    [InlineData(">= 7.2.2, < 9.4.39", "9.4.38.v20210224", true)]
    [InlineData(">= 7.2.2, < 9.4.39", "9.4.39.v20210325", false)]
    // GHSA-57j2-w4cx-62h2, jackson-databind: trailing zeros carry no order, and a fourth number does.
    [InlineData(">= 2.13.0, <= 2.13.2.0", "2.13.2", true)]
    [InlineData(">= 2.13.0, <= 2.13.2.0", "2.13.2.1", false)]
    // Maven 3 and Maven 4 read an underscore differently ("1.0_1" is 1-_-1 in one, 1-_1 in the other),
    // but every order puts it after the numbers before it.
    [InlineData("< 2.1", "2.0_1", true)]
    // "b" is beta only directly before a digit; on its own it is a qualifier Maven sorts by its text.
    [InlineData("< 2.1", "2.0-b", true)]
    // GHSA-3pxv-7cmr-fjr4, log4j-core: a pre-release lower bound admits the releases above it,
    // including the release with its own numbers.
    [InlineData(">= 2.0-alpha1, < 2.25.4", "2.17.1", true)]
    [InlineData(">= 2.0-alpha1, < 2.25.4", "2.0", true)]
    // A pre-release is decided by its numbers like any version, and sits below its own release.
    [InlineData("< 2.1", "2.0-rc1", true)]
    [InlineData("< 2.1", "2.0-cr1", true)]
    [InlineData("< 2.0", "2.0-SNAPSHOT", true)]
    [InlineData("< 2.0", "2.0.M1", true)]
    [InlineData(">= 2.0", "2.0-rc1", false)]
    public void DecidesARealMavenRange(string range, string version, bool expected) =>
        Assert.Equal(expected, VulnerableRanges.IsConfirmedInRange("maven", range, version));

    /// <summary>Each of these may be vulnerable, and the matcher cannot say, so it must not claim it.</summary>
    [Theory]
    // Two qualifiers on the same numbers are never compared: every order admits 2.0-beta9 here.
    [InlineData(">= 2.0-alpha1, < 2.25.4", "2.0-beta9")]
    // A short form needs its digit attached: Maven 4 reads "b-1" as a beta and Maven 3 does not.
    [InlineData("<= 2.0-rc-1", "2.0-b-1")]
    // Maven sorts these after the release, though they are meant to precede it, so a qualifier
    // outside the two read is undecided against the release.
    [InlineData("<= 2.1", "2.1-ea")]
    [InlineData("> 2.1", "2.1-preview")]
    // Words that read as pre-releases but that every order sorts above the release: confirming
    // these would be wrong, not merely undecided.
    [InlineData("< 2.1", "2.1-preview")]
    [InlineData("< 2.1", "2.1.pr1")]
    // Equal numbers with qualifiers this does not read. All three orders put the first outside its
    // range; Maven 3 alone puts the second inside, which is the disagreement that keeps qualifiers
    // unread.
    [InlineData("< 32.0.0-android", "32.0.0-jre")]
    [InlineData("<= 15.10-rc-1", "15.10.redhat-00001")]
    // A version that has run out of numbers before the bound's, with text after them.
    [InlineData("< 1.0.0.5", "1.0-1")]
    // Not a version this reads: no leading digit, or a character beyond ASCII.
    [InlineData("< 2.1", "v2.0")]
    [InlineData("= v2.0", "v2.0")]
    [InlineData("< 2.1", "2.0-é")]
    [InlineData("< 2.1", "")]
    public void LeavesWhatItCannotDecideUnconfirmed(string range, string version) =>
        Assert.False(VulnerableRanges.IsConfirmedInRange("maven", range, version));

    [Fact]
    public void FoldsTheEcosystemSpelling() =>
        Assert.True(VulnerableRanges.IsConfirmedInRange(" MAVEN ", "< 2.0", "1.0"));

    [Fact]
    public void RefusesAVersionLongerThanTheCap() =>
        Assert.False(VulnerableRanges.IsConfirmedInRange("maven", "< 2.0", "1." + new string('0', SemanticVersion.MaxLength)));

    /// <summary>
    /// The order where Maven 3, Maven 4 and Dependabot all agree, and null where this does not read far
    /// enough to say: equal numbers carrying a qualifier other than a lone release word or a lone
    /// pre-release against the bare release, two pre-releases against each other, or text after
    /// numbers that have run out against numbers that have not. Several null pairs are ordered alike
    /// by all three; null there is a refusal to read, not a disagreement found.
    /// </summary>
    [Theory]
    [InlineData("1", "1.1", -1)]
    [InlineData("1.0", "1", 0)]
    [InlineData("2.13.2", "2.13.2.0", 0)]
    [InlineData("01.2", "1.2", 0)]
    [InlineData("4.1.107.Final", "4.1.108.Final", -1)]
    [InlineData("1.0-FINAL", "1.0-final", 0)]
    [InlineData("10.0.0", "9.99.99-jre", 1)]
    [InlineData("1.0.Final", "1.0", 0)]
    [InlineData("1.0-ga", "1.0.RELEASE", 0)]
    [InlineData("9.4.21.V20190926", "9.4.21.v20190926", 0)]
    [InlineData("1.0-sp", "1.0", null)]
    [InlineData("1.0-rc1", "1.0", -1)]
    [InlineData("1.0", "1.0.RC-2", 1)]
    [InlineData("1.0", "1.0-cr1", 1)]
    [InlineData("1.0-b-1", "1.0", null)]
    [InlineData("1.0-rc1", "1.0-beta2", null)]
    [InlineData("1.0-rc1-foo", "1.0", null)]
    [InlineData("1.0_rc1", "1.0", null)]
    [InlineData("1.0_final", "1.0", null)]
    [InlineData("1.0.final.1", "1.0", null)]
    [InlineData("15.10.redhat-00001", "15.10-rc-1", null)]
    [InlineData("1.0-1", "1.0.0.5", null)]
    [InlineData("1.0.0.5", "1.0-1", null)]
    public void OrdersOnlyWhatEveryMavenAgreesOn(string left, string right, int? expected) =>
        Assert.Equal(expected, MavenVersion.Parse(left)!.CompareTo(MavenVersion.Parse(right)!) is { } order ? Math.Sign(order) : null);

    [Fact]
    public void NeverConfirmsWhatMavenDoesNot()
    {
        var result = RangeFixtures.Check("maven-ranges.tsv", "maven", "Maven");

        // A fixture that failed to load reads exactly like one where every case passed.
        Assert.True(result.Ranges > 1000, $"only {result.Ranges} ranges read");
        Assert.True(result.Versions > 50000, $"only {result.Versions} versions read");
        Assert.True(result.WrongOutside.Count == 0, string.Join('\n', result.WrongOutside.Take(50)));
        // Outside is also decided, not merely never wrong: about half the unclaimed versions, the rest
        // being ones it leaves undecided by design. The floor catches a change that stops deciding it.
        var unclaimed = result.Versions - result.Claimed;
        Assert.True(result.ConfirmedOutside >= unclaimed * 0.4, $"outside {result.ConfirmedOutside} of {unclaimed}");
        Assert.True(result.OverClaims.Count == 0, string.Join('\n', result.OverClaims.Take(50)));
        // Reading only the numbers leaves some of Maven's answers undecided, and this fixture is built
        // to find them: most of its versions put a qualifier on a bound's own numbers, the one case
        // left undecided. So the floor is about half here, against nearly all of a real artifact's
        // releases; it exists so a change that stops deciding most of them does not pass unnoticed.
        var confirmed = result.Claimed - result.Undecided.Count;
        Assert.True(confirmed >= result.Claimed * 0.5, $"confirmed {confirmed} of {result.Claimed}");
    }
}
